function Invoke-Child([string[]]$Arguments,[string]$Stdout,[string]$Stderr){$old=$env:PSModulePath;try{$env:PSModulePath=$native;&$winps @Arguments 1>$Stdout 2>$Stderr;return [int]$LASTEXITCODE}finally{$env:PSModulePath=$old}}
$childStdout=Join-Path $derivedRoot 'child.stdout.log';$childStderr=Join-Path $derivedRoot 'child.stderr.log';$exit=Invoke-Child @('-NoProfile','-ExecutionPolicy','Bypass','-File',$derived,'-ProjectPath',$ProjectPath,'-VerificationRoot',$VerificationRoot,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath,'-TelemetryResultPath',$TelemetryResultPath,'-UnityPath',$UnityPath) $childStdout $childStderr
