function Invoke-RepeatBlock($item){$blockPlan=New-Gate13RPR1BV2BlockPlan -ProjectPath $ProjectPath -Plan $plan -Provenance $provenance -ScheduleItem $item -ProvenancePath $ProvenancePath -TelemetryProbeResultPath $TelemetryResultPath;$planFile=Join-Path $additional 'plans\repeat.block-plan.json';Write-Gate13RPR1BV2Utf8NoBomJson -Path $planFile -Value $blockPlan -Depth 30;$output=Join-Path $additional 'repeatability\per-agent';New-Item -ItemType Directory -Path (Split-Path $output -Parent) -Force|Out-Null;$stdout=$output+'.stdout.log';$stderr=$output+'.stderr.log';$code=Invoke-Child @('-NoProfile','-ExecutionPolicy','Bypass','-File',$runner,'-ProjectPath',$ProjectPath,'-BlockPlanPath',$planFile,'-OutputDirectory',$output,'-AllowedRoot',$VerificationRoot,'-Mode','Verification','-UnityPath',$UnityPath) $stdout $stderr;if($code-ne0){throw "Independent repeat block failed: exit=$code stderr=$stderr"};$summary=Read-Gate13RPR1BV2Json ($output+'.summary.json');if($summary.passed-ne$true){throw 'Independent repeat block summary failed.'};$processRecords.Add([pscustomobject]@{kind='independent-repeat';processId=[int]$summary.unityProcessId;summarySha256=Get-Gate13RPR1BV2LowerSha256 ($output+'.summary.json')});return $output}
function Compare-Blocks([string]$left,[string]$right,[string]$label){$lm=Read-Gate13RPR1BV2Json (Join-Path $left 'block-manifest.json');$rm=Read-Gate13RPR1BV2Json (Join-Path $right 'block-manifest.json');foreach($ls in @($lm.samples)){$rs=@($rm.samples|Where-Object algorithmId -eq ([string]$ls.algorithmId));if($rs.Count-ne1){throw "Repeat sample mismatch: $label"};$a=Read-Gate13RPR1BV2Json (Join-Path $left ([string]$ls.workloadResultRelativePath).Replace('/','\'));$b=Read-Gate13RPR1BV2Json (Join-Path $right ([string]$rs[0].workloadResultRelativePath).Replace('/','\'));$cmp=Compare-Gate10RStructuralResults -Reference $a -Candidate $b;$comparisons.Add([pscustomobject]@{kind='independent-process-repeatability';label=$label;algorithmId=[string]$ls.algorithmId;referenceProjectionSha256=$cmp.referenceProjectionSha256;candidateProjectionSha256=$cmp.candidateProjectionSha256;passed=$cmp.passed});if($cmp.passed-ne$true){throw "Repeatability structural mismatch: $label/$($ls.algorithmId)"}}}
function Invoke-Cold([string]$scenarioPath,[string]$algorithm,[string]$name){$output=Join-Path $additional ('cold\'+$name);New-Item -ItemType Directory -Path (Split-Path $output -Parent) -Force|Out-Null;$stdout=$output+'.stdout.log';$stderr=$output+'.stderr.log';$code=Invoke-Child @('-NoProfile','-ExecutionPolicy','Bypass','-File',$coldRunner,'-ProjectPath',$ProjectPath,'-ScenarioPath',$scenarioPath,'-OutputDirectory',$output,'-AllowedRoot',$VerificationRoot,'-RunId',('g13r-pr1b-v2-cold-'+$name),'-Algorithm',$algorithm,'-UnityPath',$UnityPath) $stdout $stderr;if($code-ne0){throw "Cold control failed: $name exit=$code stderr=$stderr"};$summary=Read-Gate13RPR1BV2Json ($output+'.summary.json');if($summary.passed-ne$true){throw "Cold control summary failed: $name"};$processRecords.Add([pscustomobject]@{kind='cold-control';algorithmId=$algorithm;processId=[int]$summary.unityProcessId;summarySha256=Get-Gate13RPR1BV2LowerSha256 ($output+'.summary.json')});return $output}
